export default {
  id: 'stable-plugin',
  name: 'Stable Plugin',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'stable_value',
        version: '1.0.0',
        description: 'Return the stable constant value 18.',
        permissions: [],
        sideEffect: 'none',
        parameters: { type: 'object', properties: {}, required: [] },
        outputSchema: { type: 'object', properties: { value: { type: 'number' } }, required: ['value'] },
        async handler(args: unknown, tctx: unknown) {
          return { ok: true, data: { value: 18 } };
        }
      }
    });
  }
};

